    "description": "Handcrafted in Japan. #169 Dragon Eyes 24K Gold Putter (Moon & Clouds) - 4-Kamon Carbon Shaft represents the pinnacle of Honma craftsmanship, featuring precision engineering, premium materials, and bespoke artisanal finishing.",
    "description_ja": "Dragon Eyesパター商品説明：プレイヤーが構える瞬間、“すわり”がいいピタッとターゲットに対して真っ直ぐ構えられる。抜群のヘッドサイズと、ソール幅のバランス。フェースミーリング仕上げが、打感を柔らかく方向性を維持しやすい。独特なターゲットマークの、鏃(やじり)の幅がボールのセンター部をヒットしやすい。KENTACKオリジナルパター専用カーボンシャフト(一番高い弾性率40t 四軸組布使用)は、「安定した距離間」、「打点のばらつきを抑える」、「ラインに対して正確に打ち出せる」という、パターシャフトに求められる機能を実現、更に限りなくブレ幅を抑える超低トルク、絶妙なしなりがタイミングを取り易く、距離感を安定させるテンポの良いストロークを可能にします。オフセンターヒットでも、距離のバラつきが少なく、カーボン特有のマイルドなフィーリングも得る事ができます。セミオーダー：商品はご注文をいただいてから日本国内の工房で組み立てます。シャフトの長さはご要望に合わせて調整可能ですが、特に無い場合は一般的な長さで調整いたします。※お支払いをいただいてから1週間~2週間での発送になります。",
