    "description_ja": "サイズ【長さ】34inch【ロフト】3°【ライ角】71°【ヘッド重量】356g【シャフト重量】115g【グリップ重量】77.5ｇ【クラブ重量】549ｇ【製造】日本製Dragon　Eyesパター【ヘッド素材/製法】軟鉄/CNC加工【仕上げ】DLC加工【フェース加工/製法】ミーリング加工【バッチプレート】KENTACK ノーマル【製造】日本製DLC加工とは：\tDLCはDiamond like Carbonの略称です。高硬度、耐摩耗、低摩擦、凝着を起こしにくいなどの優れた特徴を持つ表面処理技術です。スチールシャフト【素材】スチール【長さ】31～36インチ【製造】日本製商品説明：プレイヤーが構える瞬間、“すわり”がいいピタッとターゲットに対して真っ直ぐ構えられる。抜群のヘッドサイズと、ソール幅のバランス。フェースミーリング仕上げが、打感を柔らかく方向性を維持しやすい。独特なターゲットマークの、鏃(やじり)の幅がボールのセンター部をヒットしやすい。セミオーダー：商品はご注文をいただいてから日本国内の工房で組み立てます。シャフトの長さはご要望に合わせて調整可能ですが、特に無い場合は一般的な長さで調整いたします。※お支払いをいただいてから1週間~2週間での発送になります。",
