    "title": "#129 DragonEyes DLC Rainbow Coating(Limited Edition 273/500) Precision Steel Shaft - Designed by Hiroo Honma",
    "title_ja": "＃129 DragonEyes DLC加工 レインボー(Serial NO.273/500)  スチールシャフト(DESIGNED by 本間裕朗)",
    "description": "Handcrafted in Japan. #129 DragonEyes DLC Rainbow Coating(Limited Edition 273/500) Precision Steel Shaft - Designed by Hiroo Honma represents the pinnacle of Honma craftsmanship, featuring precision engineering, premium materials, and bespoke artisanal finishing.",
    "description_ja": "サイズ【長さ】34inch【ロフト】3°【ライ角】71°【ヘッド重量】356g【シャフト重量】115g【グリップ重量】77.5ｇ【クラブ重量】549ｇ【製造】日本製Dragon Eyes パター【ヘッド素材/製法】軟鉄/CNC加工【仕上げ】DLC加工【フェース加工/製法】ミーリング加工【バッチプレート】螺鈿(金沢職人作)【製造】日本製【DLC加工とは： 】DLCはDiamond like Carbonの略称です。高硬度、耐摩耗、低摩擦、凝着を起こしにくいなどの優れた特徴を持つ表面処理技術です。【螺鈿細工とは：】青貝の殻の内側の、真珠色の光を放つ部分を薄く種々の形に切って、漆器などの表面にはめこんで装飾とした物です。スチールシャフト【素材】スチール【長さ】31～36インチ【製造】日本製商品説明：プレイヤーが構える瞬間、“すわり”がいいピタッとターゲットに対して真っ直ぐ構えられる。抜群のヘッドサイズと、ソール幅のバランス。フェースミーリング仕上げが、打感を柔らかく方向性を維持しやすい。独特なターゲットマークの、鏃(やじり)の幅がボールのセンター部をヒットしやすい。KENTACKオリジナルパター専用カーボンシャフト(一番高い弾性率40t 四軸組布使用)は、「安定した距離間」、「打点のばらつきを抑える」、「ラインに対して正確に打ち出せる」という、パターシャフトに求められる機能を実現、更に限りなくブレ幅を抑える超低トルク、絶妙なしなりがタイミングを取り易く、距離感を安定させるテンポの良いストロークを可能にします。オフセンターヒットでも、距離のバラつきが少なく、カーボン特有のマイルドなフィーリングも得る事ができます。セミオーダー：商品はご注文をいただいてから日本国内の工房で組み立てます。シャフトの長さはご要望に合わせて調整可能ですが、特に無い場合は一般的な長さで調整いたします。※お支払いをいただいてから1週間~2週間での発送になります。",
