let modal, modalImg, modalPrev, modalNext, modalClose;
let modalTitle, modalDesc, modalDetails, modalSpecs;
let modalImages = [];
let modalIndex = 0;
let modalTimer;

function openProductModal(product) {
  modalImages = product.images;
  modalIndex = 0;
  const lang = document.documentElement.lang || 'en';
  updateModalImage();
  if (modalTitle) {
    const titleText = (product.nameKey && translations[lang] && translations[lang][product.nameKey]) || (lang === 'ja' && product.title_ja ? product.title_ja : (product.title || product.nameKey || ''));
    modalTitle.textContent = titleText;
    if (product.id === 'kh888') {
      modalTitle.classList.add('kh888-highlight');
    } else {
      modalTitle.classList.remove('kh888-highlight');
    }
  }
  if (modalDesc) {
    const descText = (product.descKey && translations[lang] && translations[lang][product.descKey]) || (lang === 'ja' && product.description_ja ? product.description_ja : (product.description || ''));
    modalDesc.textContent = descText;
  }
  if (modalDetails) {
    if (product.detailsKey && translations[lang] && translations[lang][product.detailsKey]) {
      modalDetails.textContent = translations[lang][product.detailsKey];
    } else {
      modalDetails.textContent = '';
    }
  }
  if (modalSpecs) {
    if (product.specsKey && translations[lang] && translations[lang][product.specsKey]) {
      modalSpecs.innerHTML = translations[lang][product.specsKey];
      modalSpecs.classList.remove('hidden');
    } else if (product.specsKey && translations['en'] && translations['en'][product.specsKey]) {
      modalSpecs.innerHTML = translations['en'][product.specsKey];
      modalSpecs.classList.remove('hidden');
    } else if (product.specs_html) {
      modalSpecs.innerHTML = product.specs_html;
      modalSpecs.classList.remove('hidden');
    } else {
      modalSpecs.classList.add('hidden');
    }
  }
  modal.classList.remove('hidden', 'closing');
  const content = modal.querySelector('.modal-content');
  if (content) content.classList.remove('closing');
  document.body.classList.add('modal-open');
  modalTimer = setInterval(nextModalImage, 3000);
}

function closeProductModal() {
  if (!modal) return;
  clearInterval(modalTimer);
  const content = modal.querySelector('.modal-content');
  modal.classList.add('closing');
  if (content) content.classList.add('closing');
  const handleAnimationEnd = () => {
    modal.classList.add('hidden');
    modal.classList.remove('closing');
    if (content) content.classList.remove('closing');
  };
  if (content) {
    content.addEventListener('animationend', handleAnimationEnd, { once: true });
  } else {
    handleAnimationEnd();
  }
  document.body.classList.remove('modal-open');
}

function updateModalImage() {
  if (modalImg) {
    modalImg.classList.remove('fade');
    void modalImg.offsetWidth;
    modalImg.src = modalImages[modalIndex];
    modalImg.classList.add('fade');
  }
}

function nextModalImage() {
  modalIndex = (modalIndex + 1) % modalImages.length;
  updateModalImage();
}

function prevModalImage() {
  modalIndex = (modalIndex - 1 + modalImages.length) % modalImages.length;
  updateModalImage();
}

function initProductModal() {
  modal = document.getElementById('product-modal');
  if (!modal) return;
  modalImg = modal.querySelector('.modal-image');
  modalPrev = modal.querySelector('.prev');
  modalNext = modal.querySelector('.next');
  modalClose = modal.querySelector('.close');
  modalTitle = modal.querySelector('.modal-title');
  modalDesc = modal.querySelector('.modal-desc');
  modalDetails = modal.querySelector('.modal-details');
  modalSpecs = modal.querySelector('.modal-specs');
  if (modalImg) {
    modalImg.addEventListener('animationend', () => modalImg.classList.remove('fade'));
  }
  if (modalPrev) modalPrev.addEventListener('click', e => { e.stopPropagation(); prevModalImage(); });
  if (modalNext) modalNext.addEventListener('click', e => { e.stopPropagation(); nextModalImage(); });
  if (modalClose) modalClose.addEventListener('click', closeProductModal);
  modal.addEventListener('click', e => { if (e.target === modal) closeProductModal(); });
}

function renderProducts(filter = {}) {
  const grid = document.getElementById('product-grid');
  if (!grid) return;
  grid.innerHTML = '';
  updateProductHeading(filter);
  const lang = document.documentElement.lang || 'en';
  const items = productData.filter(p => {
    if (filter.category && p.category !== filter.category) return false;
    if (filter.type && p.type !== filter.type) return false;
    return true;
  });
  if (!items.length) {
    const msg = document.createElement('p');
    msg.setAttribute('data-i18n', 'no_products');
    msg.textContent = translations[lang].no_products;
    grid.appendChild(msg);
    return;
  }
  items.forEach(p => {
    const div = document.createElement('div');
    div.className = 'product animate';
    const name = (p.nameKey && translations[lang] && translations[lang][p.nameKey]) || (lang === 'ja' && p.title_ja ? p.title_ja : (p.title || p.nameKey || ''));
    const desc = (p.descKey && translations[lang] && translations[lang][p.descKey]) || (lang === 'ja' && p.description_ja ? p.description_ja : (p.description || ''));
    div.innerHTML = `
      <img src="${p.image}" alt="${name}" data-i18n-alt="${p.nameKey || ''}" class="product-image" loading="lazy">
      <h2 data-i18n="${p.nameKey || ''}">${name}</h2>
      <p data-i18n="${p.descKey || ''}">${desc}</p>
    `;
    div.addEventListener('click', () => openProductModal(p));
    grid.appendChild(div);
  });
  initAnimations();
}

function updateProductFilterURL(filter) {
  const params = new URLSearchParams(window.location.search);
  if (filter.type) {
    params.set('type', filter.type);
  } else {
    params.delete('type');
  }
  if (filter.category) {
    params.set('category', filter.category);
  } else {
    params.delete('category');
  }
  const queryString = params.toString();
  const newUrl = queryString ? `${window.location.pathname}?${queryString}` : window.location.pathname;
  if (history.replaceState) {
    history.replaceState({}, '', newUrl);
  }
}

function saveProductsScroll() {
  try {
    localStorage.setItem('productsScrollTop', String(window.scrollY));
  } catch (e) {
    /* ignore storage errors */
  }
}

function restoreProductsScroll() {
  const isProductsPage = window.location.pathname.endsWith('products.html') || window.location.pathname.endsWith('/products');
  if (!isProductsPage) return;
  let saved = null;
  try {
    saved = localStorage.getItem('productsScrollTop');
    if (saved !== null) {
      localStorage.removeItem('productsScrollTop');
    }
  } catch (e) {
    saved = null;
  }
  const top = saved !== null ? parseInt(saved, 10) : null;
  if (Number.isFinite(top) && top > 0) {
    requestAnimationFrame(() => {
      window.scrollTo({ top, behavior: 'auto' });
    });
  }
}

function navigateToCollection(filter) {
  saveProductsScroll();
  const params = new URLSearchParams();
  if (filter.category) params.set('category', filter.category);
  if (filter.type) params.set('type', filter.type);
  const queryString = params.toString();
  const target = queryString ? `category.html?${queryString}` : 'category.html';
  window.location.href = target;
}

function updateProductHeading(filter) {
  const heading = document.getElementById('product-heading');
  if (!heading) return;
  const lang = document.documentElement.lang || 'en';
  const t = translations[lang] || translations['en'];
  let text = (t && t.products_title) || 'Products';
  if (filter.type) {
    const typeKey = `club_${filter.type}`;
    text = (t && t[typeKey]) || filter.type;
  } else if (filter.category) {
    const categoryKey = `category_${filter.category}`;
    text = (t && t[categoryKey]) || filter.category;
  }
  heading.textContent = text;
}

function toggleCategoryHero(type) {
  const hero = document.querySelector('.category-hero');
  const label = document.querySelector('.category-hero .hero-label');
  const img = document.querySelector('.category-hero .hero-club-img');
  const heading = document.getElementById('product-heading');
  if (!hero || !label || !img) return;

  const lang = document.documentElement.lang || 'en';
  const t = translations[lang] || translations['en'];

  const heroData = {
    drivers: { textKey: 'club_drivers', src: 'products/unnamed.png', altKey: 'hero_alt_drivers', fallbackText: 'DRIVERS', fallbackAlt: 'Kentack driver hero' },
    irons: { textKey: 'club_irons', src: 'products/IMG_0260.png', altKey: 'hero_alt_irons', fallbackText: 'IRONS', fallbackAlt: 'Kentack irons hero' },
    putters: { textKey: 'club_putters', src: 'products/IMG_0261.png', altKey: 'hero_alt_putters', fallbackText: 'PUTTERS', fallbackAlt: 'Kentack putter hero' },
    rescue: { textKey: 'club_rescue', src: 'products/IMG_2505.PNG', altKey: 'hero_alt_rescue', fallbackText: 'RESCUE', fallbackAlt: 'Kentack rescue hero' },
    wedges: { textKey: 'club_wedges', src: 'products/IMG_0260.png', altKey: 'hero_alt_wedges', fallbackText: 'WEDGES', fallbackAlt: 'Kentack wedges hero' },
    accessories: { textKey: 'club_accessories', src: 'ACCESSORY/hat.png', altKey: 'hero_alt_accessories', fallbackText: 'ACCESSORIES', fallbackAlt: 'Kentack accessories hero' }
  };

  const data = heroData[type];

  if (data) {
    const text = (data.textKey && t[data.textKey]) || data.fallbackText || data.text;
    const alt = (data.altKey && t[data.altKey]) || data.fallbackAlt || data.alt;

    label.textContent = text;
    if (data.textKey) {
      label.setAttribute('data-i18n', data.textKey);
    }
    img.src = data.src;
    img.alt = alt;
    if (data.altKey) {
      img.setAttribute('data-i18n-alt', data.altKey);
    }
    hero.classList.remove('hidden');
    if (heading) heading.classList.add('hidden');
  } else {
    hero.classList.add('hidden');
    if (heading) heading.classList.remove('hidden');
  }
}

function initProducts() {
  const grid = document.getElementById('product-grid');
  if (!grid) return;
  const params = new URLSearchParams(window.location.search);
  const type = params.get('type');
  const category = params.get('category');
  const initialFilter = {};
  if (category) initialFilter.category = category;
  if (type) initialFilter.type = type;
  renderProducts(initialFilter);
  toggleCategoryHero(type);
}

function initCategoryCardFilters() {
  const cards = document.querySelectorAll('[data-category-card]');
  if (!cards.length) return;

  cards.forEach(card => {
    const type = card.getAttribute('data-type');
    const category = card.getAttribute('data-category');
    const filter = {};
    if (category) filter.category = category;
    if (type) filter.type = type;
    const goToCollection = () => navigateToCollection(filter);
    const label = card.querySelector('.club-label');
    if (label) {
      label.setAttribute('tabindex', '0');
      label.setAttribute('role', 'link');
      label.style.cursor = 'pointer';
      label.addEventListener('click', e => {
        e.stopPropagation();
        e.preventDefault();
        goToCollection();
      });
      label.addEventListener('keydown', e => {
        if (e.key === 'Enter' || e.key === ' ') {
          e.preventDefault();
          e.stopPropagation();
          goToCollection();
        }
      });
    }

    card.addEventListener('click', goToCollection);
    card.addEventListener('keydown', e => {
      if (e.key === 'Enter' || e.key === ' ') {
        e.preventDefault();
        goToCollection();
      }
    });
  });
}

function initRandomAccessory() {
  const accessoryImg = document.getElementById('accessory-feature-img');
  if (!accessoryImg) return;
  const accessories = [
    { src: 'ACCESSORY/hat.png', alt: 'Kentack hat accessory' },
    { src: 'ACCESSORY/grip.png', alt: 'Kentack grip accessory' },
    { src: 'ACCESSORY/umb.PNG', alt: 'Kentack umbrella accessory' },
    { src: 'ACCESSORY/boston.png', alt: 'Kentack Boston bag accessory' },
    { src: 'ACCESSORY/caddy.png', alt: 'Kentack caddy bag accessory' }
  ];
  const randomIndex = Math.floor(Math.random() * accessories.length);
  const chosen = accessories[randomIndex];
  accessoryImg.src = chosen.src;
  accessoryImg.alt = chosen.alt;
}

function initDemoVideo() {
  const video = document.querySelector('.product-video video');
  const subtitle = document.querySelector('.video-subtitle');
  if (!video) return;
  video.muted = true;
  video.autoplay = true;
  video.loop = true;
  video.playsInline = true;
  video.removeAttribute('controls');
  video.setAttribute('controlsList', 'nodownload noremoteplayback noplaybackrate');
  video.setAttribute('disablePictureInPicture', '');

  const tryPlay = () => {
    const playPromise = video.play();
    if (playPromise && typeof playPromise.catch === 'function') {
      playPromise.catch(() => {});
    }
  };

  const observer = new IntersectionObserver(entries => {
    entries.forEach(entry => {
      if (entry.isIntersecting) {
        tryPlay();
      }
    });
  }, { threshold: 0.35 });

  observer.observe(video);
  tryPlay();

  const updateSubtitleColor = () => {
    if (!subtitle) return;
    const t = video.currentTime;
    const withinWhiteWindow = t >= 6 && t <= 8;
    subtitle.style.color = withinWhiteWindow ? '#ffffff' : '#000000';
  };

  video.addEventListener('timeupdate', updateSubtitleColor);
  video.addEventListener('seeked', updateSubtitleColor);
  video.addEventListener('loadedmetadata', updateSubtitleColor);
  updateSubtitleColor();
}

const SITE_LOADER_MAX_MS = 15000;
const IMAGE_PRELOAD_TIMEOUT_MS = 9000;
const IMAGE_PRELOAD_CONCURRENCY = 6;
const productPreviewAssets = [
  'products/DRI.PNG',
  'products/IMG_0260.png',
  'products/IMG_0261.png',
  'products/IMG_2505.PNG',
  'ACCESSORY/hat.png',
  'ACCESSORY/grip.png',
  'ACCESSORY/umb.PNG',
  'ACCESSORY/boston.png',
  'ACCESSORY/caddy.png'
];

function wait(ms) {
  return new Promise(resolve => setTimeout(resolve, ms));
}

function updateLoader(loader, progress, status) {
  if (!loader) return;
  loader.style.setProperty('--loader-progress', `${Math.max(0, Math.min(100, progress))}%`);
  const statusEl = loader.querySelector('.loader-status');
  if (statusEl && status) {
    statusEl.textContent = status;
  }
}

function resolveAssetUrl(value, baseUrl = document.baseURI) {
  if (!value) return '';
  const trimmed = String(value).trim();
  if (!trimmed || trimmed.startsWith('#')) return '';
  if (/^(data|blob|mailto|tel|javascript):/i.test(trimmed)) return '';
  try {
    return new URL(trimmed, baseUrl).href;
  } catch (e) {
    return '';
  }
}

function parseSrcset(srcset, baseUrl) {
  if (!srcset) return [];
  return srcset
    .split(',')
    .map(candidate => candidate.trim().split(/\s+/)[0])
    .map(src => resolveAssetUrl(src, baseUrl))
    .filter(Boolean);
}

function collectImageUrlsFrom(root, baseUrl = document.baseURI) {
  const urls = [];
  root.querySelectorAll('img').forEach(img => {
    urls.push(resolveAssetUrl(img.getAttribute('src') || img.currentSrc || img.src, baseUrl));
    urls.push(...parseSrcset(img.getAttribute('srcset'), baseUrl));
  });
  root.querySelectorAll('source[srcset]').forEach(source => {
    urls.push(...parseSrcset(source.getAttribute('srcset'), baseUrl));
  });
  root.querySelectorAll('video[poster]').forEach(video => {
    urls.push(resolveAssetUrl(video.getAttribute('poster'), baseUrl));
  });
  return urls.filter(Boolean);
}

function collectProductAssetUrls() {
  const urls = productPreviewAssets.map(src => resolveAssetUrl(src));
  if (Array.isArray(productData)) {
    productData.slice(0, 24).forEach(product => {
      urls.push(resolveAssetUrl(product.image));
      if (Array.isArray(product.images)) {
        product.images.slice(0, 2).forEach(src => urls.push(resolveAssetUrl(src)));
      }
    });
  }
  return urls.filter(Boolean);
}

function getProductsPageUrl() {
  return resolveAssetUrl('products.html');
}

async function fetchProductsDocument() {
  const productsUrl = getProductsPageUrl();
  if (!productsUrl) return null;
  const currentPath = window.location.pathname.replace(/\/+$/, '');
  if (currentPath.endsWith('/products.html') || currentPath.endsWith('/products')) {
    return document;
  }
  if (window.location.protocol === 'file:') {
    return null;
  }
  const response = await fetch(productsUrl, { cache: 'force-cache' });
  if (!response.ok) {
    throw new Error(`Unable to preload products.html: ${response.status}`);
  }
  const html = await response.text();
  return new DOMParser().parseFromString(html, 'text/html');
}

function preloadImage(url) {
  return new Promise(resolve => {
    const image = new Image();
    let settled = false;
    const finish = ok => {
      if (settled) return;
      settled = true;
      clearTimeout(timer);
      resolve({ ok, url });
    };
    const timer = setTimeout(() => finish(false), IMAGE_PRELOAD_TIMEOUT_MS);
    image.onload = () => finish(true);
    image.onerror = () => finish(false);
    image.src = url;
    if (image.complete) {
      finish(image.naturalWidth > 0);
    }
  });
}

function preloadImages(urls, loader, startProgress, endProgress, status) {
  const uniqueUrls = Array.from(new Set(urls.filter(Boolean)));
  if (!uniqueUrls.length) {
    updateLoader(loader, endProgress, status);
    return Promise.resolve([]);
  }

  let active = 0;
  let completed = 0;
  let index = 0;
  const failures = [];

  updateLoader(loader, startProgress, status);

  return new Promise(resolve => {
    const runNext = () => {
      if (completed === uniqueUrls.length) {
        updateLoader(loader, endProgress, status);
        resolve(failures);
        return;
      }

      while (active < IMAGE_PRELOAD_CONCURRENCY && index < uniqueUrls.length) {
        const url = uniqueUrls[index];
        index += 1;
        active += 1;
        preloadImage(url).then(result => {
          active -= 1;
          completed += 1;
          if (!result.ok) failures.push(result.url);
          const progress = startProgress + ((endProgress - startProgress) * completed / uniqueUrls.length);
          updateLoader(loader, progress, status);
          runNext();
        });
      }
    };

    runNext();
  });
}

function waitForWindowLoaded() {
  if (document.readyState === 'complete') {
    return Promise.resolve();
  }
  return new Promise(resolve => {
    window.addEventListener('load', resolve, { once: true });
  });
}

function waitForFontsReady() {
  if (!document.fonts || !document.fonts.ready) {
    return Promise.resolve();
  }
  return document.fonts.ready.catch(() => {});
}

async function runSitePreload(loader) {
  updateLoader(loader, 18, 'Loading page');
  const fontsReadyPromise = waitForFontsReady();
  const pageImageUrls = collectImageUrlsFrom(document);
  const pageImagesReadyPromise = preloadImages(pageImageUrls, loader, 28, 92, 'Loading images');
  await waitForWindowLoaded();
  updateLoader(loader, 92, 'Finishing page');
  await pageImagesReadyPromise;
  await fontsReadyPromise;
  updateLoader(loader, 100, 'Ready');
}

async function warmProductsAssetsInBackground() {
  let productImageUrls = collectProductAssetUrls();
  try {
    const productsDocument = await fetchProductsDocument();
    if (productsDocument) {
      productImageUrls = productImageUrls.concat(collectImageUrlsFrom(productsDocument, getProductsPageUrl()));
    }
  } catch (error) {
    console.warn(error);
  }

  const productFailures = await preloadImages(productImageUrls, null, 0, 100, '');
  if (productFailures.length) {
    console.warn('Some product assets could not be preloaded:', productFailures);
  }
}

async function initSiteLoader() {
  const loader = document.getElementById('site-loader');
  if (!loader) {
    document.body.classList.add('site-loaded');
    await wait(0);
    document.body.classList.add('site-content-ready');
    return;
  }

  const preload = runSitePreload(loader).catch(error => {
    console.warn('Site preload skipped:', error);
  });
  const timeout = wait(SITE_LOADER_MAX_MS).then(() => {
    console.warn('Site preload timed out; releasing loader.');
  });

  await Promise.race([preload, timeout]);
  updateLoader(loader, 100, 'Ready');
  document.body.classList.add('site-loaded');
  loader.setAttribute('aria-hidden', 'true');
  await waitForLoaderExit(loader);
  document.body.classList.add('site-content-ready');
  warmProductsAssetsInBackground();
}

document.addEventListener('DOMContentLoaded', () => {
  initLanguage();
  initTheme();
  initDeviceDetection();
  initMobileMenu();
  initNavScroll();
  initRandomAccessory();
  initProducts();
  initIntroScroll();
  initProductModal();
  initCategoryCardFilters();
  initProductDeepLink();
  initPutterModalTrigger();
  restoreProductsScroll();
  initDemoVideo();
  initSiteLoader().then(() => {
    initAnimations();
    initProductsIntroAnimation();
  });
});
